def svg(name, size=16, color="currentColor", stroke=2):
    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
            f'stroke="{color}" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round" '
            f'style="vertical-align:-0.15em;flex:none" aria-hidden="true">{ICONS[name]}</svg>')


def data_uri(name, color="#000", stroke=2):
    raw = svg(name, 24, color, stroke).replace(' style="vertical-align:-0.15em;flex:none"', "")
    return "data:image/svg+xml;base64," + base64.b64encode(raw.encode()).decode()


def mask_rule(selector, name, size="1.05em", gap=".45rem"):
    """CSS that puts a Lucide icon (inheriting the text colour) before a Streamlit button label."""
    u = data_uri(name)
    return (f"{selector} p{{display:inline-flex;align-items:center;gap:{gap};}}"
            f"{selector} p::before{{content:'';width:{size};height:{size};flex:none;background:currentColor;"
            f"-webkit-mask:url({u}) center/contain no-repeat;mask:url({u}) center/contain no-repeat;}}")
